import 'package:flutter/material.dart'; import '../../data/model/auth_user_dto.dart'; import 'view_models/barbers_view_model.dart';
class BarbersScreen extends StatefulWidget { const BarbersScreen({super.key,required this.user,required this.viewModel}); final AuthUserDto user; final BarbersViewModel viewModel; @override State<BarbersScreen> createState()=>_BarbersScreenState(); }
class _BarbersScreenState extends State<BarbersScreen>{@override void initState(){super.initState();widget.viewModel.addListener(_reload);widget.viewModel.load();}void _reload(){if(mounted)setState((){});}@override void dispose(){widget.viewModel.removeListener(_reload);super.dispose();}@override Widget build(BuildContext context){if(widget.viewModel.loading&&widget.viewModel.items.isEmpty)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:[Text('Equipe',style:Theme.of(context).textTheme.headlineSmall),...widget.viewModel.items.map((b)=>ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(b.name),subtitle:Text('${b.role} · ${b.workStart}–${b.workEnd}'),trailing:Text('${b.commissionRate.toStringAsFixed(0)}%')))]);}}
